-- A brought-forward loan is an opening receivable, not a bank disbursement.
-- This foundation does not itself enable billing: historical accrued interest
-- and the already-satisfied minimum still need explicit opening-state support.
-- journal_id is the stable opening reference. For zero principal it identifies the
-- reviewed record only and does not refer to a journal; for positive principal it
-- is also the posted principal journal ID.
CREATE TABLE loan_openings (
 loan_id TEXT PRIMARY KEY REFERENCES loans(id), journal_id TEXT NOT NULL UNIQUE,
 member_id TEXT NOT NULL, principal_minor INTEGER NOT NULL CHECK(principal_minor>=0), currency TEXT NOT NULL,
 reviewed_original_principal INTEGER NOT NULL, reviewed_disbursement_date TEXT NOT NULL,
 opening_date TEXT NOT NULL, receivable_account_id TEXT NOT NULL, clearing_account_id TEXT NOT NULL,
 source TEXT NOT NULL CHECK(length(trim(source))>0), created_by TEXT NOT NULL,
 request_key TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE loan_opening_corrections (
 id TEXT PRIMARY KEY, loan_id TEXT NOT NULL REFERENCES loans(id), original_journal_id TEXT NOT NULL UNIQUE,
 original_request_key TEXT NOT NULL UNIQUE, original_details TEXT NOT NULL, reversal_journal_id TEXT UNIQUE,
 reason TEXT NOT NULL CHECK(length(trim(reason))>0), request_key TEXT NOT NULL UNIQUE, created_by TEXT NOT NULL, period_open_confirmed INTEGER NOT NULL CHECK(period_open_confirmed=1),
 status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','final')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TRIGGER loan_opening_insert_guard BEFORE INSERT ON loan_openings BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM loan_opening_corrections WHERE original_request_key=NEW.request_key) THEN RAISE(ABORT,'opening request key already used') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') OR NOT EXISTS(SELECT 1 FROM loans l WHERE l.id=NEW.loan_id AND l.member_id=NEW.member_id AND l.principal_minor=NEW.reviewed_original_principal AND l.currency=NEW.currency AND l.disbursement_date=NEW.reviewed_disbursement_date AND NEW.opening_date>=l.disbursement_date AND NEW.principal_minor<=l.principal_minor AND NOT EXISTS(SELECT 1 FROM loan_source_voids v WHERE v.source_kind='loan' AND v.source_id=l.id)) THEN RAISE(ABORT,'opening loan changed or unauthorized') END;
 SELECT CASE WHEN NEW.receivable_account_id=NEW.clearing_account_id OR NOT EXISTS(SELECT 1 FROM ledger_accounts WHERE id=NEW.receivable_account_id AND currency=NEW.currency) OR NOT EXISTS(SELECT 1 FROM ledger_accounts WHERE id=NEW.clearing_account_id AND currency=NEW.currency) THEN RAISE(ABORT,'invalid opening accounts') END;
 SELECT CASE WHEN NEW.opening_date>date('now') OR EXISTS(SELECT 1 FROM loan_repayments WHERE loan_id=NEW.loan_id) OR EXISTS(SELECT 1 FROM journal_entries WHERE source_type='loan-disbursement' AND source_id=NEW.loan_id) OR EXISTS(SELECT 1 FROM loan_billing_configs WHERE loan_id=NEW.loan_id) THEN RAISE(ABORT,'loan already has activity or opening date is in the future') END;
END;
CREATE TRIGGER loan_opening_immutable BEFORE UPDATE ON loan_openings BEGIN SELECT RAISE(ABORT,'opening is immutable'); END;
CREATE TRIGGER loan_opening_no_delete BEFORE DELETE ON loan_openings WHEN NOT EXISTS(SELECT 1 FROM loan_opening_corrections c WHERE c.loan_id=OLD.loan_id AND c.original_journal_id=OLD.journal_id AND c.status='final') BEGIN SELECT RAISE(ABORT,'opening requires reviewed correction'); END;
CREATE TRIGGER loan_opening_journal_guard BEFORE UPDATE OF status ON journal_entries WHEN NEW.status='posted' AND NEW.source_type='loan-opening' BEGIN
 SELECT CASE WHEN NEW.reverses_entry_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM loan_openings o WHERE o.journal_id=NEW.source_id AND o.journal_id=NEW.id AND o.created_by=NEW.created_by AND o.currency=NEW.currency AND o.opening_date=NEW.effective_date AND EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') AND (SELECT count(*) FROM journal_lines WHERE entry_id=NEW.id)=2 AND EXISTS(SELECT 1 FROM journal_lines WHERE entry_id=NEW.id AND side='debit' AND account_id=o.receivable_account_id AND amount_minor=o.principal_minor) AND EXISTS(SELECT 1 FROM journal_lines WHERE entry_id=NEW.id AND side='credit' AND account_id=o.clearing_account_id AND amount_minor=o.principal_minor)) THEN RAISE(ABORT,'opening journal must match reviewed opening') END;
END;
CREATE TRIGGER loan_opening_no_disbursement BEFORE UPDATE OF status ON journal_entries WHEN NEW.status='posted' AND NEW.source_type='loan-disbursement' AND EXISTS(SELECT 1 FROM loan_openings WHERE loan_id=NEW.source_id) BEGIN SELECT RAISE(ABORT,'opening loan cannot also be disbursed'); END;
-- Keep an opening from silently disappearing while a correction workflow is pending.
CREATE TRIGGER loan_opening_void_guard BEFORE INSERT ON loan_source_voids WHEN NEW.source_kind='loan' AND EXISTS(SELECT 1 FROM loan_openings WHERE loan_id=NEW.source_id) BEGIN SELECT RAISE(ABORT,'opening loan requires an opening correction'); END;
CREATE TRIGGER loan_opening_reversal_guard BEFORE UPDATE OF status ON journal_entries WHEN NEW.status='posted' AND NEW.reverses_entry_id IS NOT NULL AND EXISTS(SELECT 1 FROM loan_openings WHERE journal_id=NEW.reverses_entry_id) BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM loan_opening_corrections c WHERE c.original_journal_id=NEW.reverses_entry_id AND c.reversal_journal_id=NEW.id AND c.created_by=NEW.created_by AND c.status='pending' AND NEW.source_type='loan-opening-reversal' AND NEW.source_id=c.id) THEN RAISE(ABORT,'opening reversal requires an opening correction') END; END;
CREATE TRIGGER loan_opening_correction_insert BEFORE INSERT ON loan_opening_corrections BEGIN SELECT CASE WHEN NEW.status<>'pending' OR NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') OR EXISTS(SELECT 1 FROM loan_billing_configs WHERE loan_id=NEW.loan_id) OR NOT EXISTS(SELECT 1 FROM loan_openings o WHERE o.loan_id=NEW.loan_id AND o.journal_id=NEW.original_journal_id AND o.request_key=NEW.original_request_key AND ((o.principal_minor=0 AND NEW.reversal_journal_id IS NULL) OR (o.principal_minor>0 AND NEW.reversal_journal_id IS NOT NULL))) THEN RAISE(ABORT,'opening changed, unauthorized, or billing active') END; END;
CREATE TRIGGER loan_opening_correction_update BEFORE UPDATE ON loan_opening_corrections BEGIN SELECT CASE WHEN OLD.status<>'pending' OR NEW.status<>'final' OR NEW.id IS NOT OLD.id OR NEW.loan_id IS NOT OLD.loan_id OR NEW.original_journal_id IS NOT OLD.original_journal_id OR NEW.original_request_key IS NOT OLD.original_request_key OR NEW.original_details IS NOT OLD.original_details OR NEW.reversal_journal_id IS NOT OLD.reversal_journal_id OR NEW.reason IS NOT OLD.reason OR NEW.request_key IS NOT OLD.request_key OR NEW.created_by IS NOT OLD.created_by OR NEW.period_open_confirmed IS NOT OLD.period_open_confirmed OR NEW.created_at IS NOT OLD.created_at OR NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') OR NOT EXISTS(SELECT 1 FROM loan_openings o WHERE o.loan_id=NEW.loan_id AND o.journal_id=NEW.original_journal_id AND ((o.principal_minor=0 AND NEW.reversal_journal_id IS NULL) OR (o.principal_minor>0 AND EXISTS(SELECT 1 FROM journal_entries j JOIN journal_entries orig ON orig.id=NEW.original_journal_id WHERE j.id=NEW.reversal_journal_id AND j.status='posted' AND j.reverses_entry_id=orig.id AND j.effective_date=orig.effective_date)))) THEN RAISE(ABORT,'opening correction incomplete or immutable') END; END;
CREATE TRIGGER loan_opening_correction_no_delete BEFORE DELETE ON loan_opening_corrections BEGIN SELECT RAISE(ABORT,'opening correction immutable'); END;
CREATE TRIGGER loan_opening_loan_guard BEFORE UPDATE OF id,member_id,principal_minor,currency,disbursement_date ON loans WHEN (EXISTS(SELECT 1 FROM loan_openings WHERE loan_id=OLD.id) OR EXISTS(SELECT 1 FROM loan_opening_corrections WHERE loan_id=OLD.id)) AND (NEW.id IS NOT OLD.id OR NEW.member_id IS NOT OLD.member_id OR NEW.principal_minor IS NOT OLD.principal_minor OR NEW.currency IS NOT OLD.currency OR NEW.disbursement_date IS NOT OLD.disbursement_date) BEGIN SELECT RAISE(ABORT,'opening loan source is immutable'); END;
